"""
make_preview.py - build a local test page (Leaflet + OpenStreetMap) for a georeferenced sheet.

Usage:  python3 make_preview.py sheets/<sheet>/fit_result.json sheets/<sheet>/tile_bounds.json <dir_containing_tiles> "<title>"

Writes index.html next to the tiles/ folder. Open it by double-clicking: it shows the
new tiles over OpenStreetMap, the live site's Arcanum 1KF layer for comparison, the
control points (green = today, red = where the map puts it) and their residuals.
Clicking the map shows lat/lon, to correct a control point in gcps.json.
"""
import json, math, sys, os
fit_path, bounds_path, out_dir, title = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
g=json.load(open(fit_path, encoding="utf-8"))
pts=[{k:p[k] for k in ("id","name","role","px","py","lat","lon","fit_lat","fit_lon","resid_m")} for p in g["points"]]
fit=[p for p in pts if p["role"]=="fit"]
rms=round(math.sqrt(sum(p["resid_m"]**2 for p in fit)/len(fit)))
t=g["transform_3857"]; lat=sum(p["lat"] for p in fit)/len(fit); k=1/math.cos(math.radians(lat))
nb={int(z):b for z,b in json.load(open(bounds_path)).items()}
TEMPLATE = '<!DOCTYPE html>\n<html lang="tr">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>__TITLE__ Georeferans Testi</title>\n<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">\n<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>\n<style>\n  html,body{margin:0;height:100%;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:14px;color:#222}\n  #wrap{display:flex;height:100%}\n  #map{flex:1}\n  #side{width:380px;overflow-y:auto;padding:14px 16px;border-left:1px solid #ddd;background:#fafafa;box-sizing:border-box}\n  h1{font-size:17px;margin:0 0 4px}\n  .sub{color:#666;font-size:12.5px;margin-bottom:12px}\n  .box{background:#fff;border:1px solid #e3e3e3;border-radius:6px;padding:10px 12px;margin-bottom:12px}\n  .box h2{font-size:13px;margin:0 0 6px;text-transform:uppercase;letter-spacing:.04em;color:#555}\n  label{display:flex;align-items:center;gap:6px;margin:4px 0;cursor:pointer}\n  input[type=range]{width:100%}\n  table{width:100%;border-collapse:collapse;font-size:12.5px}\n  td,th{padding:4px 4px;border-bottom:1px solid #eee;text-align:left;vertical-align:top}\n  tr.pt{cursor:pointer} tr.pt:hover{background:#f0f4ff}\n  .r{text-align:right;font-variant-numeric:tabular-nums}\n  .dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:4px;vertical-align:-1px}\n  .good{color:#1a7f37}.mid{color:#b26b00}.bad{color:#c62828}\n  #click{font-family:ui-monospace,Menlo,monospace;font-size:12px;background:#f3f3f3;padding:6px;border-radius:4px;word-break:break-all;min-height:1.2em}\n  ol{padding-left:18px;margin:4px 0} li{margin:3px 0}\n  .legend span{display:inline-flex;align-items:center;margin-right:10px;font-size:12.5px}\n</style>\n</head>\n<body>\n<div id="wrap">\n<div id="map"></div>\n<div id="side">\n  <h1>__TITLE__ &mdash; Georeferans testi</h1>\n  <div class="sub">__SHEET__</div>\n\n  <div class="box">\n    <h2>Katmanlar</h2>\n    <label><input type="checkbox" id="lyrNew" checked> Yeni pafta (bu test)</label>\n    <div style="margin-left:22px">Opaklık <span id="opv">70%</span><input type="range" id="op" min="0" max="1" step="0.05" value="0.7"></div>\n    <label><input type="checkbox" id="lyrSite"> Sitedeki mevcut 1KF katmanı (karşılaştırma)</label>\n    <label><input type="checkbox" id="lyrPts" checked> Kontrol noktaları</label>\n    <div class="legend" style="margin-top:6px">\n      <span><span class="dot" style="background:#1a7f37"></span>bugünkü konum</span>\n      <span><span class="dot" style="background:#c62828"></span>haritadaki konum</span>\n    </div>\n  </div>\n\n  <div class="box">\n    <h2>Nasıl kontrol edilir</h2>\n    <ol>\n      <li><b>Genel oturma:</b> Opaklığı oynat. Tuna, Gellért Tepesi, Vár tepesi ve Pest\'in eski surları (Kiskörút) altlıkla örtüşmeli.</li>\n      <li><b>Noktalar:</b> Tabloda bir satıra tıkla. Yeşil nokta, o yapının bugünkü yeri olmalı. Değilse benim koordinatım yanlış demektir.</li>\n      <li><b>Bağımsız referans:</b> "Sitedeki mevcut 1KF katmanı"nı aç, yeni paftayı kapatıp aç. Arcanum\'un kendi georeferansıyla ne kadar örtüştüğünü görürsün.</li>\n      <li><b>Düzeltme:</b> Haritada bir yere tıklarsan koordinatı aşağıda çıkar. Yanlış noktanın doğru yerini bana yollaman yeterli, yeniden fit ederim.</li>\n    </ol>\n  </div>\n\n  <div class="box">\n    <h2>Fit sonucu</h2>\n    <div>Piksel boyu: <b>__SCALE__ m</b> (nominal 2.438 m)<br>Dönüş: <b>__ROT__°</b> &middot; Fit noktaları RMS: <b>__RMS__ m</b></div>\n    <table style="margin-top:8px">\n      <thead><tr><th>Nokta</th><th>Rol</th><th class="r">Sapma</th></tr></thead>\n      <tbody id="tbl"></tbody>\n    </table>\n    <div class="sub" style="margin-top:6px">"fit" noktaları georeferansı hesaplamak için kullanıldı. "kontrol" noktaları sadece test için. Bu iki köy kilisesinin koordinatları yaklaşık.</div>\n  </div>\n\n  <div class="box">\n    <h2>Tıkladığın nokta</h2>\n    <div id="click">Haritaya tıkla&hellip;</div>\n  </div>\n</div>\n</div>\n<script>\nvar PTS = __PTS__;\nvar SITE_BOUNDS = {6:{xMin:34,xMax:36,yMin:22,yMax:22},7:{xMin:69,xMax:72,yMin:44,yMax:45},8:{xMin:139,xMax:144,yMin:88,yMax:91},9:{xMin:278,xMax:288,yMin:176,yMax:182},10:{xMin:557,xMax:577,yMin:353,yMax:365},11:{xMin:1114,xMax:1154,yMin:706,yMax:731},12:{xMin:2228,xMax:2309,yMin:1412,yMax:1463},13:{xMin:4457,xMax:4619,yMin:2825,yMax:2926},14:{xMin:8914,xMax:9239,yMin:5651,yMax:5852}};\nvar NEW_BOUNDS = __NB__;\n\nvar Bounded = L.TileLayer.extend({\n  _isValidTile: function(c){\n    if(!L.TileLayer.prototype._isValidTile.call(this,c)) return false;\n    var b=this.options.tileBounds && this.options.tileBounds[c.z]; if(!b) return false;\n    return c.x>=b.xMin&&c.x<=b.xMax&&c.y>=b.yMin&&c.y<=b.yMax;\n  }\n});\nvar map = L.map(\'map\',{maxZoom:18}).setView([47.515,19.10],12);\nL.tileLayer(\'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png\',{maxZoom:19,attribution:\'&copy; OpenStreetMap contributors\'}).addTo(map);\nvar site = new Bounded(\'https://danfront-tiles.odulsuzkisafilm.workers.dev/tiles/{z}/{x}/{y}.png\',{maxNativeZoom:14,maxZoom:18,opacity:0.7,tileBounds:SITE_BOUNDS});\nvar neu  = new Bounded(\'tiles/{z}/{x}/{y}.png\',{maxNativeZoom:14,maxZoom:18,opacity:0.7,tileBounds:NEW_BOUNDS}).addTo(map);\nvar ptsLayer = L.layerGroup().addTo(map);\n\nfunction cls(m){return m<=150?\'good\':(m<=400?\'mid\':\'bad\');}\nvar tbl=document.getElementById(\'tbl\');\nPTS.forEach(function(p){\n  var today=[p.lat,p.lon], onmap=[p.fit_lat,p.fit_lon];\n  L.polyline([today,onmap],{color:\'#333\',weight:1.5,dashArray:\'4 4\'}).addTo(ptsLayer);\n  var pop=\'<b>\'+p.name+\'</b><br>Rol: \'+(p.role===\'fit\'?\'fit\':\'kontrol\')+\'<br>Sapma: <b>\'+p.resid_m+\' m</b><br>\'+\n          \'<span style="color:#1a7f37">&#9679;</span> bugün: \'+p.lat.toFixed(5)+\', \'+p.lon.toFixed(5)+\'<br>\'+\n          \'<span style="color:#c62828">&#9679;</span> haritada: \'+p.fit_lat.toFixed(5)+\', \'+p.fit_lon.toFixed(5)+\'<br>\'+\n          \'<span style="color:#888">sayfa pikseli: \'+p.px+\', \'+p.py+\'</span>\';\n  L.circleMarker(today,{radius:7,color:\'#fff\',weight:2,fillColor:\'#1a7f37\',fillOpacity:1}).bindPopup(pop).addTo(ptsLayer);\n  L.circleMarker(onmap,{radius:6,color:\'#fff\',weight:2,fillColor:\'#c62828\',fillOpacity:1}).bindPopup(pop).addTo(ptsLayer);\n  var tr=document.createElement(\'tr\'); tr.className=\'pt\';\n  tr.innerHTML=\'<td>\'+p.name+\'</td><td>\'+(p.role===\'fit\'?\'fit\':\'kontrol\')+\'</td><td class="r \'+cls(p.resid_m)+\'">\'+p.resid_m+\' m</td>\';\n  tr.onclick=function(){ map.setView(today,16); };\n  tbl.appendChild(tr);\n});\ndocument.getElementById(\'op\').oninput=function(){ neu.setOpacity(+this.value); site.setOpacity(+this.value); document.getElementById(\'opv\').textContent=Math.round(this.value*100)+\'%\'; };\nfunction tog(id,l){ document.getElementById(id).onchange=function(){ this.checked?map.addLayer(l):map.removeLayer(l); }; }\ntog(\'lyrNew\',neu); tog(\'lyrSite\',site); tog(\'lyrPts\',ptsLayer);\nmap.on(\'click\',function(e){ document.getElementById(\'click\').textContent=e.latlng.lat.toFixed(5)+\', \'+e.latlng.lng.toFixed(5); });\n</script>\n</body>\n</html>\n'
html=TEMPLATE
for a,b in {"__PTS__":json.dumps(pts,ensure_ascii=False),"__NB__":json.dumps(nb),
            "__SCALE__":f"{math.hypot(t['a'],t['c'])/k:.3f}","__ROT__":f"{math.degrees(math.atan2(t['c'],t['a'])):+.2f}",
            "__RMS__":str(rms),"__TITLE__":title,"__SHEET__":g.get("sheet","")}.items():
    html=html.replace(a,b)
open(os.path.join(out_dir,"index.html"),"w",encoding="utf-8").write(html)
print("wrote", os.path.join(out_dir,"index.html"))
